{
  "title": "Working in Nextcloud",
  "theme": "nextcloud",
  "paginate": true,
  "slides": [
    {
      "title": "Agenda",
      "summary": "What Nextcloud is, files and sharing, calendar and contacts, Talk collaboration, and where to get help."
    },
    {
      "title": "What Is Nextcloud?",
      "summary": "Our company hub for documents and communication: one place for files, calendars, contacts and chats, in our own data center."
    },
    {
      "title": "Files and Sharing",
      "summary": "Every project lives in its folder. Share with internal links, request uploads with file drops, and set expiry dates on external shares."
    },
    {
      "title": "Calendar and Contacts",
      "summary": "Book rooms and meetings from the shared calendar; your contacts sync to your phone; invitations update by email automatically."
    },
    {
      "title": "Collaborating in Talk",
      "summary": "Project channels replace long email threads; share files in the chat; start a call from any conversation when writing is too slow."
    },
    {
      "title": "Where to Get Help",
      "summary": "The Handbook space in Nextcloud, the help desk channel in Talk, and the IT self-service portal for account issues."
    }
  ]
}
